
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_bkl2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_bkl2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-9.389663077241051e-02, -9.299595993043426e-02, -9.169993815611663e-02, -8.983447715912168e-02, -8.714805487019804e-02, -8.327674104515978e-02, -7.769601683599339e-02, -6.967480271576515e-02, -5.837828085609292e-02, -4.413879360987145e-02, -3.604053266549558e-02, -5.283728446816927e-02, -5.364283869492509e-02, -4.559002583641517e-02, -3.251929894736390e-02, -1.551028723428147e-02, -2.138799202717677e-03, -2.802665581007031e-05, -3.018428507429932e-08, -1.197882656619915e-12]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


